const state={admin:null,csrf:null,tab:'dashboard',assetView:'tools',cache:{},netCache:new Map(),inflight:new Map(),loadSeq:0,warmed:false};
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=v=>{if(!v)return'';const d=new Date(v);return new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(d)};
const fmtMoney=(n,c='NGN')=>new Intl.NumberFormat(undefined,{style:'currency',currency:c,currencyDisplay:'narrowSymbol'}).format((Number(n)||0)/100);
const human=s=>String(s||'').replaceAll('_',' ').replace(/\b\w/g,m=>m.toUpperCase());
const initials=n=>String(n||'TC').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
async function api(path,opts={}){
  const method=(opts.method||'GET').toUpperCase();
  const cacheable=method==='GET'&&path.startsWith('/api/admin/');
  const now=Date.now(),ttl=15000;
  if(cacheable){
    const hit=state.netCache.get(path);
    if(hit&&now-hit.time<ttl)return hit.data;
    if(state.inflight.has(path))return state.inflight.get(path);
  }else if(method!=='GET'&&method!=='HEAD'){
    state.netCache.clear();
  }
  const run=(async()=>{
    const headers=new Headers(opts.headers||{});
    let body=opts.body;
    if(body&&!(body instanceof FormData)){headers.set('content-type','application/json');body=typeof body==='string'?body:JSON.stringify(body)}
    if(state.csrf&&!['GET','HEAD'].includes(method))headers.set('x-csrf-token',state.csrf);
    const res=await fetch(path,{credentials:'same-origin',...opts,method,body,headers,cache:cacheable?'no-store':opts.cache});
    const d=await res.json().catch(()=>({ok:false,error:'Invalid server response.'}));
    if(!res.ok){const e=new Error(d.error||'Something went wrong.');e.status=res.status;throw e}
    if(cacheable)state.netCache.set(path,{time:Date.now(),data:d});
    return d;
  })();
  if(cacheable){state.inflight.set(path,run);run.finally(()=>state.inflight.delete(path));}
  return run;
}
function toast(m,t='ok'){const e=document.createElement('div');e.className=`toast ${t}`;e.textContent=m;$('#toastHost').append(e);setTimeout(()=>e.remove(),3500)}
function setupStatus(message='',type='info'){const el=$('#adminSetupStatus');if(!el)return;if(!message){el.textContent='';el.className='admin-setup-status hidden';return}el.textContent=message;el.className=`admin-setup-status ${type}`;}
function empty(t,p){return `<div class="empty-state"><span>◇</span><h3>${esc(t)}</h3><p>${esc(p)}</p></div>`}
function badge(s){const cls=['success','active','online','resolved'].includes(s)?'ok':['failed','disabled','closed'].includes(s)?'warn':'';return `<span class="status-badge ${cls}">${esc(human(s))}</span>`}
function icon(a){return `<div class="app-icon" style="--accent:${esc(a.accent_color||'#7b65ff')}">${a.icon_url?`<img src="${esc(a.icon_url)}" alt="">`:esc(initials(a.name))}</div>`}

async function boot(){bind();try{const s=await api('/api/admin/session');state.admin=s.admin;state.csrf=s.csrfToken;enterShell();await loadTab('dashboard');scheduleWarmup()}catch{$('#adminLogin').classList.remove('hidden')}}
function enterShell(){$('#adminLogin').classList.add('hidden');$('#adminShell').classList.remove('hidden');$('#adminIdentity').innerHTML=`<strong>${esc(state.admin.fullName)}</strong><span>${esc(state.admin.role)} · ${esc(state.admin.email)}</span><small class="admin-build">V2.5</small>`}
function bind(){
  $('#adminLoginForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),b=$('button',e.currentTarget);b.disabled=true;try{const d=await api('/api/admin/login',{method:'POST',body:{email:f.get('email'),password:f.get('password')}});state.admin=d.admin;state.csrf=d.csrfToken;enterShell();await loadTab('dashboard');scheduleWarmup()}catch(err){toast(err.message,'error');b.disabled=false}});
  $('#showAdminSetup')?.addEventListener('click',()=>{setupStatus();$('#adminLoginForm').classList.add('hidden');$('#showAdminSetup').classList.add('hidden');$('#adminSetupForm').classList.remove('hidden')});
  $('#cancelAdminSetup')?.addEventListener('click',()=>{setupStatus();$('#adminSetupForm').classList.add('hidden');$('#adminLoginForm').classList.remove('hidden');$('#showAdminSetup').classList.remove('hidden')});
  $('#adminSetupForm')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),b=form.querySelector('button[type=submit]'),original=b.textContent;const email=String(f.get('email')||'').trim(),password=String(f.get('password')||'');setupStatus('Creating the owner administrator…','info');b.disabled=true;b.textContent='Creating administrator…';try{const token=String(f.get('bootstrapToken')||'');const d=await api('/api/admin/bootstrap',{method:'POST',headers:{'x-toolcart-bootstrap-token':token},body:{fullName:f.get('fullName'),email,password}});if(d.admin&&d.csrfToken){state.admin=d.admin;state.csrf=d.csrfToken;setupStatus('Owner administrator created. Opening the Admin dashboard…','success');toast('Owner administrator created.');form.reset();enterShell();await loadTab('dashboard');scheduleWarmup();return}if(d.created&&d.requiresLogin){setupStatus(d.message||'Owner administrator created. Sign in with the credentials you just chose.','success');$('#adminLoginForm').elements.email.value=email;$('#adminLoginForm').elements.password.value=password;form.classList.add('hidden');$('#adminLoginForm').classList.remove('hidden');$('#showAdminSetup').classList.remove('hidden');toast('Owner administrator created. Sign in to continue.');return}setupStatus(d.message||'Owner administrator created.','success')}catch(err){setupStatus(err.message||'Administrator setup failed.','error');toast(err.message||'Administrator setup failed.','error')}finally{b.disabled=false;b.textContent=original}});
  document.addEventListener('click',async e=>{
    const nav=e.target.closest('[data-admin-tab]');if(nav){closeModal();return loadTab(nav.dataset.adminTab)}
    if(e.target.closest('[data-close-admin-modal]')||e.target.id==='modalBackdrop')return closeModal();
    const assetView=e.target.closest('[data-asset-view]');if(assetView){state.assetView=assetView.dataset.assetView==='products'?'products':'tools';renderAssetManager();return}
    const createKind=e.target.closest('[data-create-kind]');if(createKind){const kind=createKind.dataset.createKind==='product'?'product':'app';state.assetView=kind==='product'?'products':'tools';showModal(creatorModal(kind));return kind==='product'?bindProductForm():bindAppForm()}
    const open=e.target.closest('[data-open]');if(open)return handleOpen(open.dataset.open,open.dataset.id);
    const action=e.target.closest('[data-action]');if(action)return handleAction(action);
    if(e.target.id==='adminMenuBtn')return $('#adminSidebar').classList.toggle('open');
    if(e.target.id==='adminMore')return showMore();
    if(e.target.id==='adminRefresh')return loadTab(state.tab,true);
  });
  $('#adminLogout').addEventListener('click',async()=>{try{await api('/api/admin/logout',{method:'POST'})}catch{}location.reload()});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#adminSidebar').classList.remove('open')}})
}
async function loadTab(tab,refresh=false){
  if(tab==='products'){state.assetView='products';tab='apps'}
  const seq=++state.loadSeq;state.tab=tab;
  $('#adminPageTitle').textContent=tab==='apps'?'Tools & Products':human(tab);
  $$('[data-admin-tab]').forEach(b=>b.classList.toggle('active',b.dataset.adminTab===tab));
  $('#adminSidebar').classList.remove('open');
  if(refresh)state.netCache.clear();
  $('#adminContent').innerHTML=adminLoading(tab==='apps'?'Tools & Products':human(tab));
  try{
    if(tab==='dashboard')await dashboard();else if(tab==='customers')await customers();else if(tab==='apps')await apps();else if(tab==='subscriptions')await subscriptions();else if(tab==='payments')await payments();else if(tab==='updates')await updates();else if(tab==='requests')await requests();else if(tab==='notifications')await notifications();else if(tab==='analytics')await analytics();else if(tab==='appearance')await appearance();else if(tab==='settings')await settings();else if(tab==='audit')await auditLog();else if(tab==='diagnostics')await diagnostics();else $('#adminContent').innerHTML=empty('Not available','This section is not ready.');
    if(seq!==state.loadSeq)return;
  }catch(e){if(seq!==state.loadSeq)return;if(e.status===401)return location.reload();$('#adminContent').innerHTML=empty('Could not load this section',e.message)}
}
function adminLoading(label){return `<div class="admin-fast-loading"><div class="admin-loading-head"><span></span><strong>Opening ${esc(label)}…</strong></div><div class="admin-skeleton-grid"><i></i><i></i><i></i></div></div>`}
function scheduleWarmup(){
  if(state.warmed)return;state.warmed=true;
  const run=async()=>{for(const path of ['/api/admin/apps','/api/admin/products','/api/admin/requests','/api/admin/customers','/api/admin/subscriptions/plans']){try{await api(path)}catch{} await new Promise(r=>setTimeout(r,40));}};
  if('requestIdleCallback'in window)requestIdleCallback(()=>run(),{timeout:1200});else setTimeout(run,500);
}


async function dashboard(){const d=await api('/api/admin/dashboard');const m=d.metrics;const cards=[['Total customers',m.totalCustomers],['Active customers',m.activeCustomers],['New signups',m.newSignups],['Paid subscribers',m.paidSubscribers],['Monthly revenue',fmtMoney(m.monthlyRevenueMinor,'NGN')],['Tools online',m.appsOnline],['Maintenance',m.appsMaintenance],['Open requests',m.openRequests],['New requests',m.unreadRequests],['Notifications sent',m.notificationsSent]];$('#adminContent').innerHTML=`<div class="metric-grid">${cards.map((c,i)=>`<article class="metric-card" style="animation-delay:${i*35}ms"><span>${esc(c[0])}</span><strong>${esc(c[1])}</strong><small>Live ecosystem metric</small></article>`).join('')}</div><div class="admin-grid-2"><section class="admin-panel"><div class="admin-panel-head"><h2>Recent payments</h2><button class="text-btn" data-admin-tab="payments">View all</button></div>${tablePayments(d.recentPayments)}</section><section class="admin-panel"><div class="admin-panel-head"><h2>Recent tool activity</h2></div>${d.recentActivity.length?`<div class="timeline">${d.recentActivity.map(x=>`<div class="timeline-item"><small>${fmtDate(x.created_at)}</small><p><strong>${esc(x.full_name)}</strong><br>Opened ${esc(x.app_name)}</p></div>`).join('')}</div>`:empty('No activity yet','Tool opens will appear here.')}</section></div>`}

async function customers(q=''){const d=await api(`/api/admin/customers${q?`?q=${encodeURIComponent(q)}`:''}`);$('#adminContent').innerHTML=`<div class="admin-toolbar"><div class="search-field"><span>⌕</span><input id="customerSearch" placeholder="Search name, email, phone or customer ID" value="${esc(q)}"></div></div><section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Customer</th><th>ID</th><th>Plan</th><th>Status</th><th>Joined</th></tr></thead><tbody>${d.customers.map(u=>`<tr data-open="customer" data-id="${u.id}"><td><strong>${esc(u.full_name)}</strong><br>${esc(u.email)}</td><td>${esc(u.customer_id)}</td><td>${esc(u.plan_name||'Free')}</td><td>${badge(u.status)}</td><td>${fmtDate(u.created_at)}</td></tr>`).join('')}</tbody></table></div></section>`;let t;$('#customerSearch').addEventListener('input',e=>{clearTimeout(t);t=setTimeout(()=>customers(e.target.value),280)})}
async function openCustomer(id){const d=await api(`/api/admin/customers/${id}`),u=d.user;showModal(`<div class="detail-hero"><span class="eyebrow">${esc(u.customerId)}</span><h2>${esc(u.fullName)}</h2><p>${esc(u.email)}${u.phone?` · ${esc(u.phone)}`:''}</p><div class="detail-meta">${badge(u.status)}<span class="status-badge">${esc(d.currentPlan?.name||'Free')}</span><span class="status-badge">Balance ${fmtMoney(d.wallet?.balanceMinor||0,d.wallet?.currency||'NGN')}</span></div></div><div class="admin-actions"><button class="btn btn-secondary compact" data-action="customer-wallet" data-id="${id}">Adjust balance</button><button class="btn btn-secondary compact" data-action="customer-disable" data-id="${id}">${u.status==='disabled'?'Restore account':'Disable account'}</button><button class="btn btn-secondary compact" data-action="customer-gift" data-id="${id}">Gift subscription</button><button class="btn btn-secondary compact" data-action="customer-notify" data-id="${id}">Send notification</button><button class="btn btn-secondary compact admin-danger" data-action="customer-delete" data-id="${id}" data-email="${esc(u.email)}">Delete</button></div><section class="admin-panel" style="margin-top:16px"><div class="admin-panel-head"><h2>Recent payments</h2></div>${tablePayments(d.payments)}</section><section class="admin-panel" style="margin-top:12px"><div class="admin-panel-head"><h2>Requests</h2></div>${d.requests.length?d.requests.slice(0,8).map(r=>`<div class="timeline-item"><small>${esc(r.reference_number)} · ${fmtDate(r.updated_at)}</small><p><strong>${esc(r.subject)}</strong><br>${esc(human(r.status))}</p></div>`).join(''):empty('No requests','This customer has no support requests.')}</section>`)}

async function apps(view=state.assetView||'tools'){
  const [d,p]=await Promise.all([api('/api/admin/apps'),api('/api/admin/products')]);
  state.cache.appMeta=d;state.cache.products=p.products||[];state.assetView=view==='products'?'products':'tools';renderAssetManager();
}
function renderAssetManager(){
  const tools=state.cache.appMeta?.apps||[],products=state.cache.products||[],showProducts=state.assetView==='products';
  const switcher=`<div class="asset-manager-switch"><button class="${!showProducts?'active':''}" data-asset-view="tools">Tools <span>${tools.length}</span></button><button class="${showProducts?'active':''}" data-asset-view="products">Products <span>${products.length}</span></button></div>`;
  const toolCards=tools.length?tools.map(a=>`<article class="admin-app-card" data-open="app" data-id="${a.id}">${icon(a)}<h3>${esc(a.name)}</h3><p>${esc(a.short_description||'No description')}</p><div class="admin-card-foot">${badge(a.status)}<span class="muted">#${a.display_order}</span></div></article>`).join(''):empty('No tools','Add your first ToolCart tool.');
  const productCards=products.length?products.map(p=>`<article class="admin-app-card product-admin-card" data-open="product" data-id="${p.id}"><div class="product-admin-cover">${p.display_image_url?`<img src="${esc(p.display_image_url)}" alt="">`:`<span>${esc(initials(p.name))}</span>`}</div><h3>${esc(p.name)}</h3><p>${esc(p.short_description||'Digital product')}</p><div class="product-admin-meta"><span>${p.access_type==='free'?'FREE':fmtMoney(p.price_minor,p.currency)}</span><span>${esc(p.stock_label)}</span><span>${Number(p.asset_count||0)} file${Number(p.asset_count||0)===1?'':'s'}</span></div><div class="admin-card-foot">${badge(p.active?'active':'disabled')}<span class="muted">${p.premium?'Premium · ':''}${Number(p.sold_quantity||0)} sold</span></div></article>`).join(''):empty('No products','Add your first PDF or image product.');
  $('#adminContent').innerHTML=`<div class="admin-toolbar asset-manager-toolbar"><div style="flex:1"><span class="eyebrow">ECOSYSTEM CONTENT</span><h2 style="margin:5px 0 6px">Tools & Products</h2><p class="muted">Switch between website tools and downloadable products without leaving this section.</p></div><button class="btn btn-primary compact" data-action="asset-new">${showProducts?'Add product':'Add new tool'}</button></div>${switcher}<div class="admin-cards ${showProducts?'product-admin-grid':''}">${showProducts?productCards:toolCards}</div>`;
}
function creatorModal(kind=state.assetView==='products'?'product':'app'){
  const product=kind==='product';return `<div class="asset-create-switch"><span class="eyebrow">WHAT ARE YOU ADDING?</span><div><button type="button" class="${!product?'active':''}" data-create-kind="app">Tool</button><button type="button" class="${product?'active':''}" data-create-kind="product">Product</button></div></div>${product?productForm():appForm()}`;
}
function appForm(a={}){const m=state.cache.appMeta||{categories:[],plans:[]};return `<h2>${a.id?'Edit app':'Add new tool'}</h2><p class="modal-sub">Changes publish to ToolCart immediately. No redeployment is required.</p><form id="appForm" class="form-grid" data-id="${a.id||''}"><div class="admin-form-row"><div class="field"><label>Tool name</label><input name="name" value="${esc(a.name||'')}" required></div><div class="field"><label>Display order</label><input name="displayOrder" type="number" value="${a.display_order||0}"></div></div><div class="field"><label>Tool icon</label><div style="display:flex;align-items:center;gap:12px"><div class="admin-icon-preview" id="appIconPreview">${a.icon_url?`<img src="${esc(a.icon_url)}">`:'ICON'}</div><input id="appIconFile" type="file" accept="image/png,image/jpeg,image/webp"><input type="hidden" name="iconKey" value="${esc(a.icon_key||'')}"></div></div><div class="field"><label>Tool URL</label><input name="url" type="url" value="${esc(a.url||'')}" placeholder="https://..."></div><div class="field"><label>Short description</label><input name="shortDescription" maxlength="240" value="${esc(a.short_description||'')}"></div><div class="field"><label>Long description</label><textarea name="longDescription">${esc(a.long_description||'')}</textarea></div><div class="admin-form-row"><div class="field"><label>Category</label><select name="categoryId"><option value="">None</option>${m.categories.map(c=>`<option value="${c.id}" ${a.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status">${['online','maintenance','coming_soon','private','disabled'].map(x=>`<option value="${x}" ${a.status===x?'selected':''}>${human(x)}</option>`).join('')}</select></div></div><div class="admin-form-row"><div class="field"><label>Visibility</label><select name="visibility"><option value="public" ${a.visibility!=='private'?'selected':''}>Public</option><option value="private" ${a.visibility==='private'?'selected':''}>Private</option></select></div><div class="field"><label>Required plan</label><select name="requiredPlanId"><option value="">None</option>${m.plans.map(p=>`<option value="${p.id}" ${a.required_plan_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div></div><div class="field"><label>Maintenance / coming soon message</label><textarea name="maintenanceMessage">${esc(a.maintenance_message||'')}</textarea></div><div class="field"><label>Accent color</label><input name="accentColor" type="color" value="${esc(a.accent_color||'#7C5CFF')}"></div><div class="admin-form-row"><label class="setting-toggle"><div><strong>Enabled</strong></div><input class="switch" name="enabled" type="checkbox" ${a.enabled!==0?'checked':''}></label><label class="setting-toggle"><div><strong>Subscription required</strong></div><input class="switch" name="subscriptionRequired" type="checkbox" ${a.subscription_required?'checked':''}></label></div><div class="admin-form-row"><label class="setting-toggle"><div><strong>New badge</strong></div><input class="switch" name="badgeNew" type="checkbox" ${a.badge_new?'checked':''}></label><label class="setting-toggle"><div><strong>Beta badge</strong></div><input class="switch" name="badgeBeta" type="checkbox" ${a.badge_beta?'checked':''}></label></div><div class="admin-form-row"><label class="setting-toggle"><div><strong>Popular badge</strong></div><input class="switch" name="badgePopular" type="checkbox" ${a.badge_popular?'checked':''}></label><label class="setting-toggle"><div><strong>Featured</strong></div><input class="switch" name="badgeFeatured" type="checkbox" ${a.badge_featured?'checked':''}></label></div><button class="btn btn-primary">${a.id?'Save changes':'Create tool'}</button>${a.id?`<button type="button" class="btn btn-secondary admin-danger" data-action="app-delete" data-id="${a.id}">Delete tool</button>`:''}</form>`}
function bindAppForm(){const form=$('#appForm');if(!form)return;$('#appIconFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const optimized=await optimizeImage(file,512,.86);const fd=new FormData();fd.append('file',optimized,'app-icon.webp');const d=await api('/api/admin/uploads/icon',{method:'POST',body:fd});form.elements.iconKey.value=d.key;$('#appIconPreview').innerHTML=`<img src="${esc(d.url)}">`;toast('Icon uploaded.')}catch(err){toast(err.message,'error')}});form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form);const body={name:f.get('name'),url:f.get('url'),shortDescription:f.get('shortDescription'),longDescription:f.get('longDescription'),iconKey:f.get('iconKey'),categoryId:f.get('categoryId')||null,displayOrder:Number(f.get('displayOrder')||0),status:f.get('status'),visibility:f.get('visibility'),requiredPlanId:f.get('requiredPlanId')||null,accentColor:f.get('accentColor'),maintenanceMessage:f.get('maintenanceMessage'),enabled:form.elements.enabled.checked,subscriptionRequired:form.elements.subscriptionRequired.checked,badgeNew:form.elements.badgeNew.checked,badgeBeta:form.elements.badgeBeta.checked,badgePopular:form.elements.badgePopular.checked,badgeFeatured:form.elements.badgeFeatured.checked};try{const id=form.dataset.id;await api(id?`/api/admin/apps/${id}`:'/api/admin/apps',{method:id?'PATCH':'POST',body});closeModal();toast(id?'Tool updated.':'Tool created.');state.assetView='tools';loadTab('apps')}catch(err){toast(err.message,'error')}})}

async function products(){state.assetView='products';return apps('products')}
function normalizeAdminAssets(p={}){const list=Array.isArray(p.assets)&&p.assets.length?p.assets:(p.file_key?[{id:null,file_key:p.file_key,file_name:p.file_name,file_type:p.file_type,mime_type:p.mime_type,display_order:0}]:[]);return list.map((a,i)=>({id:a.id||null,fileKey:a.fileKey||a.file_key,fileName:a.fileName||a.file_name,fileType:a.fileType||a.file_type,mimeType:a.mimeType||a.mime_type,displayOrder:Number(a.displayOrder??a.display_order??i)||0})).filter(a=>a.fileKey)}
function productAssetListHtml(assets=[]){return assets.length?assets.map((a,i)=>`<div class="product-asset-row"><div><strong>${esc(a.fileName||`File ${i+1}`)}</strong><span>${esc((a.fileType||'file').toUpperCase())}</span></div><button type="button" class="micro-btn admin-danger" data-remove-product-asset="${i}">Remove</button></div>`).join(''):`<div class="product-assets-empty">No product files uploaded yet.</div>`}
function productForm(p={}){const free=p.access_type==='free';const unlimited=p.stock_mode==='unlimited';const assets=normalizeAdminAssets(p);return `<h2>${p.id?'Edit product':'Add product'}</h2><p class="modal-sub">Upload one PDF or as many protected product images as you need. Customers only receive the files after purchase, unless the product is free.</p><form id="productForm" class="form-grid" data-id="${p.id||''}"><div class="admin-form-row"><div class="field"><label>Product name</label><input name="name" value="${esc(p.name||'')}" required></div><div class="field"><label>Display order</label><input name="displayOrder" type="number" value="${p.display_order||0}"></div></div><div class="field"><label>Display image</label><div class="product-upload-row"><div class="product-admin-cover preview" id="productCoverPreview">${p.display_image_url?`<img src="${esc(p.display_image_url)}">`:'IMAGE'}</div><input id="productCoverFile" type="file" accept="image/png,image/jpeg,image/webp"><input type="hidden" name="displayImageKey" value="${esc(p.display_image_key||'')}"></div><small class="muted">This single image is the product thumbnail shown in the ToolCart launcher and product page.</small></div><div class="field"><label>Product files (PDFs or images)</label><input id="productAssetFiles" type="file" accept="application/pdf,image/png,image/jpeg,image/webp" multiple><input type="hidden" name="assetsJson" value="${esc(JSON.stringify(assets))}"><small id="productFileLabel" class="muted">Select as many images as you need, or include PDFs. Each individual file can be up to 25 MB.</small><div id="productAssetList" class="product-asset-list">${productAssetListHtml(assets)}</div></div><div class="field"><label>Short description</label><input name="shortDescription" maxlength="280" value="${esc(p.short_description||'')}"></div><div class="field"><label>Full explanation</label><textarea name="description" rows="7">${esc(p.description||'')}</textarea></div><div class="admin-form-row"><div class="field"><label>Access</label><select name="accessType"><option value="paid" ${!free?'selected':''}>Paid</option><option value="free" ${free?'selected':''}>Free</option></select></div><div class="field"><label>Price</label><input name="price" type="number" min="0" step="0.01" value="${free?'0':(Number(p.price_minor||0)/100)}"></div></div><div class="admin-form-row"><div class="field"><label>Currency</label><input name="currency" maxlength="3" value="${esc(p.currency||'NGN')}"></div><div class="field"><label>Stock mode</label><select name="stockMode"><option value="finite" ${!unlimited?'selected':''}>Limited stock</option><option value="unlimited" ${unlimited?'selected':''}>Unlimited stock</option></select></div></div><div class="field" id="stockQuantityField"><label>Amount in stock</label><input name="stockQuantity" type="number" min="0" value="${p.stock_quantity||0}"></div><div class="admin-form-row"><label class="setting-toggle"><div><strong>Active</strong><span>Visible to customers</span></div><input class="switch" name="active" type="checkbox" ${p.active!==0?'checked':''}></label><label class="setting-toggle"><div><strong>Premium</strong><span>Show premium status</span></div><input class="switch" name="premium" type="checkbox" ${p.premium?'checked':''}></label></div><label class="setting-toggle"><div><strong>Featured</strong><span>Prioritize in the launcher</span></div><input class="switch" name="featured" type="checkbox" ${p.featured?'checked':''}></label><button class="btn btn-primary">${p.id?'Save product':'Create product'}</button>${p.id?`<button type="button" class="btn btn-secondary admin-danger" data-action="product-delete" data-id="${p.id}">Delete product</button>`:''}</form>`}
function bindProductForm(){const form=$('#productForm');if(!form)return;let assets=[];try{assets=JSON.parse(form.elements.assetsJson.value||'[]')}catch{assets=[]}const list=$('#productAssetList'),label=$('#productFileLabel');const syncAssets=()=>{form.elements.assetsJson.value=JSON.stringify(assets);list.innerHTML=productAssetListHtml(assets)};const sync=()=>{form.elements.price.disabled=form.elements.accessType.value==='free';$('#stockQuantityField').classList.toggle('hidden',form.elements.stockMode.value==='unlimited')};form.elements.accessType.addEventListener('change',sync);form.elements.stockMode.addEventListener('change',sync);sync();list?.addEventListener('click',e=>{const b=e.target.closest('[data-remove-product-asset]');if(!b)return;assets.splice(Number(b.dataset.removeProductAsset),1);syncAssets()});$('#productCoverFile')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const optimized=await optimizeImage(file,900,.88);const fd=new FormData();fd.append('file',optimized,'product-cover.webp');const d=await api('/api/admin/uploads/product-cover',{method:'POST',body:fd});form.elements.displayImageKey.value=d.key;$('#productCoverPreview').innerHTML=`<img src="${esc(d.url)}">`;toast('Display image uploaded.')}catch(err){toast(err.message,'error')}});$('#productAssetFiles')?.addEventListener('change',async e=>{const files=[...e.target.files];if(!files.length)return;const input=e.target;input.disabled=true;try{for(let i=0;i<files.length;i++){const file=files[i];label.textContent=`Uploading ${i+1} of ${files.length}: ${file.name}`;const fd=new FormData();fd.append('file',file,file.name);const d=await api('/api/admin/uploads/product-file',{method:'POST',body:fd});assets.push({fileKey:d.key,fileName:d.fileName,fileType:d.fileType,mimeType:d.mimeType,displayOrder:assets.length});syncAssets()}label.textContent=`${files.length} file${files.length===1?'':'s'} uploaded. You can select more whenever you want.`;toast(`${files.length} product file${files.length===1?'':'s'} uploaded.`)}catch(err){label.textContent='One of the uploads failed. Files that completed are still listed below.';toast(err.message,'error')}finally{input.disabled=false;input.value=''}});form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form);if(!assets.length)return toast('Upload at least one product PDF or image first.','error');const free=f.get('accessType')==='free';const first=assets[0];const body={name:f.get('name'),displayImageKey:f.get('displayImageKey'),assets,fileKey:first.fileKey,fileName:first.fileName,fileType:first.fileType,mimeType:first.mimeType,shortDescription:f.get('shortDescription'),description:f.get('description'),accessType:f.get('accessType'),priceMinor:free?0:Math.round(Number(f.get('price')||0)*100),currency:String(f.get('currency')||'NGN').toUpperCase(),stockMode:f.get('stockMode'),stockQuantity:Number(f.get('stockQuantity')||0),active:form.elements.active.checked,premium:form.elements.premium.checked,featured:form.elements.featured.checked,displayOrder:Number(f.get('displayOrder')||0)};try{const id=form.dataset.id;await api(id?`/api/admin/products/${id}`:'/api/admin/products',{method:id?'PATCH':'POST',body});closeModal();toast(id?'Product updated.':'Product created.');state.assetView='products';loadTab('apps')}catch(err){toast(err.message,'error')}})}

async function subscriptions(){const d=await api('/api/admin/subscriptions/plans');state.cache.plans=d.plans;$('#adminContent').innerHTML=`<div class="admin-toolbar"><div style="flex:1"><span class="eyebrow">ACCESS</span><h2 style="margin:5px 0 0">Subscription plans</h2></div><button class="btn btn-primary compact" data-action="plan-new">Add plan</button></div><div class="admin-cards">${d.plans.map(p=>`<article class="admin-app-card" data-open="plan" data-id="${p.id}"><div class="subscription-icon">${esc(p.name[0])}</div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="admin-card-foot"><strong>${fmtMoney(p.price_minor,p.currency)}</strong>${badge(p.enabled?'active':'disabled')}</div></article>`).join('')}</div>`}
function planForm(p={}){const feats=(p.features||[]).join('\n');return `<h2>${p.id?'Edit plan':'Add plan'}</h2><form id="planForm" class="form-grid" data-id="${p.id||''}"><div class="admin-form-row"><div class="field"><label>Name</label><input name="name" value="${esc(p.name||'')}" required></div><div class="field"><label>Display order</label><input name="displayOrder" type="number" value="${p.display_order||0}"></div></div><div class="admin-form-row"><div class="field"><label>Price in minor units</label><input name="priceMinor" type="number" min="0" value="${p.price_minor||0}"></div><div class="field"><label>Currency</label><input name="currency" maxlength="3" value="${esc(p.currency||'NGN')}"></div></div><div class="field"><label>Billing frequency</label><select name="billingFrequency">${['one_time','monthly','quarterly','yearly','custom'].map(x=>`<option value="${x}" ${p.billing_frequency===x?'selected':''}>${human(x)}</option>`).join('')}</select></div><div class="field"><label>Description</label><textarea name="description">${esc(p.description||'')}</textarea></div><div class="field"><label>Features, one per line</label><textarea name="features">${esc(feats)}</textarea></div><div class="admin-form-row"><div class="field"><label>Support level</label><input name="supportLevel" value="${esc(p.support_level||'standard')}"></div><div class="field"><label>Trial days</label><input name="trialDays" type="number" min="0" value="${p.trial_days||0}"></div></div><label class="setting-toggle"><div><strong>Plan enabled</strong></div><input class="switch" name="enabled" type="checkbox" ${p.enabled!==0?'checked':''}></label><button class="btn btn-primary">Save plan</button></form>`}
function bindPlanForm(){const form=$('#planForm');form?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form),body={name:f.get('name'),priceMinor:Number(f.get('priceMinor')),currency:f.get('currency'),billingFrequency:f.get('billingFrequency'),description:f.get('description'),features:String(f.get('features')).split('\n').map(x=>x.trim()).filter(Boolean),supportLevel:f.get('supportLevel'),trialDays:Number(f.get('trialDays')),displayOrder:Number(f.get('displayOrder')),enabled:form.elements.enabled.checked};try{const id=form.dataset.id;await api(id?`/api/admin/subscriptions/plans/${id}`:'/api/admin/subscriptions/plans',{method:id?'PATCH':'POST',body});closeModal();toast('Plan saved.');loadTab('subscriptions')}catch(err){toast(err.message,'error')}})}

async function payments(){const d=await api('/api/admin/payments');$('#adminContent').innerHTML=`<section class="admin-panel"><div class="admin-panel-head"><h2>Payment center</h2><span class="muted">Server verified records</span></div>${tablePayments(d.payments,true)}</section>`}
function tablePayments(rows,admin=false){return rows?.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Customer</th><th>Amount</th><th>Purpose</th><th>Status</th><th>Reference</th><th>Date</th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.full_name||'Customer')}</strong><br>${esc(p.email||'')}</td><td>${fmtMoney(p.amount_minor,p.currency)}</td><td>${esc(p.purpose)}</td><td>${badge(p.status)}</td><td>${esc(p.provider_reference||'')}</td><td>${fmtDate(p.paid_at||p.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No payments yet','Payment activity will appear here.')}

async function updates(){const d=await api('/api/admin/updates');$('#adminContent').innerHTML=`<div class="admin-toolbar"><div style="flex:1"><span class="eyebrow">PUBLISHING</span><h2 style="margin:5px 0 0">Updates</h2></div><button class="btn btn-primary compact" data-action="update-new">Create update</button></div><section class="admin-panel">${d.updates.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Title</th><th>Type</th><th>Priority</th><th>Status</th><th>Publish</th></tr></thead><tbody>${d.updates.map(u=>`<tr data-open="update" data-id="${u.id}"><td><strong>${esc(u.title)}</strong><br>${esc((u.summary||'').slice(0,70))}</td><td>${human(u.update_type)}</td><td>${badge(u.priority)}</td><td>${badge(u.status)}</td><td>${fmtDate(u.publish_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No updates','Publish your first ecosystem update.')}</section>`;state.cache.updates=d.updates}
function updateForm(){return `<h2>Create update</h2><p class="modal-sub">Publish to the ecosystem. A linked in-site notification can be generated automatically.</p><form id="updateForm" class="form-grid"><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Summary</label><input name="summary" maxlength="400"></div><div class="field"><label>Full content</label><textarea name="content" required></textarea></div><div class="admin-form-row"><div class="field"><label>Type</label><select name="updateType">${['announcement','new','important','maintenance','feature','security'].map(x=>`<option value="${x}">${human(x)}</option>`).join('')}</select></div><div class="field"><label>Priority</label><select name="priority"><option>normal</option><option>important</option><option>urgent</option></select></div></div><div class="field"><label>External URL (optional)</label><input name="externalUrl" type="url"></div><div class="field"><label>CTA label</label><input name="ctaLabel"></div><label class="setting-toggle"><div><strong>Pin update</strong></div><input class="switch" name="pinned" type="checkbox"></label><label class="setting-toggle"><div><strong>Send in-site notification</strong></div><input class="switch" name="sendNotification" type="checkbox"></label><button class="btn btn-primary">Publish update</button></form>`}
function bindUpdateForm(){const f=$('#updateForm');f?.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(f);try{await api('/api/admin/updates',{method:'POST',body:{title:d.get('title'),summary:d.get('summary'),content:d.get('content'),updateType:d.get('updateType'),priority:d.get('priority'),externalUrl:d.get('externalUrl'),ctaLabel:d.get('ctaLabel'),pinned:f.elements.pinned.checked,sendNotification:f.elements.sendNotification.checked,status:'published'}});closeModal();toast('Update published.');loadTab('updates')}catch(err){toast(err.message,'error')}})}

async function requests(){const d=await api('/api/admin/requests');state.cache.requests=d.requests;$('#adminContent').innerHTML=`<div class="admin-toolbar"><div class="search-field"><span>⌕</span><input id="requestSearch" placeholder="Search requests"></div></div>${d.requests.length?d.requests.map(r=>`<article class="admin-request-row" data-open="request" data-id="${r.id}"><div><strong>${esc(r.subject)}</strong><p>${esc(r.reference_number)} · ${esc(r.full_name)} · ${esc(r.email)}</p></div>${badge(r.status)}</article>`).join(''):empty('No requests','Customer support requests will appear here.')}`;let t;$('#requestSearch').addEventListener('input',e=>{clearTimeout(t);t=setTimeout(async()=>{const q=e.target.value;const x=await api(`/api/admin/requests?q=${encodeURIComponent(q)}`);state.cache.requests=x.requests;$('#adminContent').querySelectorAll('.admin-request-row').forEach(x=>x.remove());requestsRenderFiltered(x.requests)},250)})}
function requestsRenderFiltered(rows){const toolbar=$('.admin-toolbar',$('#adminContent'));toolbar.insertAdjacentHTML('afterend',rows.length?rows.map(r=>`<article class="admin-request-row" data-open="request" data-id="${r.id}"><div><strong>${esc(r.subject)}</strong><p>${esc(r.reference_number)} · ${esc(r.full_name)} · ${esc(r.email)}</p></div>${badge(r.status)}</article>`).join(''):empty('No matches','Try another search.'))}
function openAdminRequest(id){const r=state.cache.requests?.find(x=>x.id===Number(id));if(!r)return;showModal(`<div class="detail-hero"><span class="eyebrow">${esc(r.reference_number)}</span><h2>${esc(r.subject)}</h2><p>${esc(r.initial_message)}</p><div class="detail-meta">${badge(r.status)}<span class="status-badge">${esc(r.email)}</span></div></div><form id="adminRequestForm" class="form-grid" data-id="${id}"><div class="field"><label>Status</label><select name="status">${['received','under_review','in_progress','resolved','closed'].map(x=>`<option value="${x}" ${r.status===x?'selected':''}>${human(x)}</option>`).join('')}</select></div><div class="field"><label>Staff response</label><textarea name="message" placeholder="Optional response to customer"></textarea></div><button class="btn btn-primary">Update request</button></form>`);$('#adminRequestForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/api/admin/requests/${id}/respond`,{method:'POST',body:{status:f.get('status'),message:f.get('message')}});closeModal();toast('Request updated.');loadTab('requests')}catch(err){toast(err.message,'error')}})}

async function notifications(){const d=await api('/api/admin/notifications');$('#adminContent').innerHTML=`<div class="admin-toolbar"><div style="flex:1"><span class="eyebrow">DELIVERY</span><h2 style="margin:5px 0 0">Notifications</h2></div><button class="btn btn-primary compact" data-action="notification-new">Send notification</button></div><section class="admin-panel">${d.notifications.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Title</th><th>Audience</th><th>Delivered</th><th>Opened</th><th>Date</th></tr></thead><tbody>${d.notifications.map(n=>`<tr><td><strong>${esc(n.title)}</strong><br>${esc(n.message.slice(0,75))}</td><td>${human(n.audience_type)}</td><td>${n.recipients}</td><td>${n.opened}</td><td>${fmtDate(n.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No notifications','Send an ecosystem notification when you are ready.')}</section>`}
function notificationForm(){return `<h2>Send notification</h2><form id="notificationForm" class="form-grid"><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Message</label><textarea name="message" required></textarea></div><div class="admin-form-row"><div class="field"><label>Importance</label><select name="importance"><option>normal</option><option>important</option><option>urgent</option></select></div><div class="field"><label>Audience</label><select name="audienceType"><option value="all">All customers</option><option value="single_user">One customer ID</option><option value="plan">Subscription plan ID</option><option value="app_users">Users of app ID</option></select></div></div><div class="field"><label>Audience ID when required</label><input name="audienceValue" type="number"></div><div class="field"><label>Destination URL (optional)</label><input name="destinationValue"></div><button class="btn btn-primary">Send notification</button></form>`}
function bindNotificationForm(){const f=$('#notificationForm');f?.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(f),type=d.get('audienceType'),v=Number(d.get('audienceValue'));const values=type==='all'?[]:v?[v]:[];try{await api('/api/admin/notifications',{method:'POST',body:{title:d.get('title'),message:d.get('message'),importance:d.get('importance'),audienceType:type,audienceValues:values,destinationType:d.get('destinationValue')?'url':null,destinationValue:d.get('destinationValue')}});closeModal();toast('Notification sent.');loadTab('notifications')}catch(err){toast(err.message,'error')}})}

async function analytics(){const d=await api('/api/admin/analytics');const max=Math.max(1,...d.appOpens.map(x=>Number(x.opens)));$('#adminContent').innerHTML=`<div class="admin-grid-2"><section class="admin-panel"><div class="admin-panel-head"><h2>Tool opens</h2><span class="muted">All time</span></div>${d.appOpens.length?`<div class="mini-chart">${d.appOpens.slice(0,15).map(x=>`<div class="mini-bar" title="${esc(x.name)}: ${x.opens}" style="height:${Math.max(5,(Number(x.opens)/max)*100)}%"></div>`).join('')}</div><div class="timeline" style="margin-top:12px">${d.appOpens.slice(0,8).map(x=>`<div class="timeline-item"><small>${x.unique_users} unique users</small><p><strong>${esc(x.name)}</strong><br>${x.opens} opens</p></div>`).join('')}</div>`:empty('No tool data','Analytics begin when customers open tools.')}</section><section class="admin-panel"><div class="admin-panel-head"><h2>Notification engagement</h2></div><div class="metric-card"><span>Delivered</span><strong>${d.notifications?.delivered||0}</strong><small>${d.notifications?.opened||0} opened</small></div><div class="admin-panel-head" style="margin-top:18px"><h2>30-day signups</h2></div><div class="timeline">${d.signups.slice(-10).map(x=>`<div class="timeline-item"><small>${esc(x.day)}</small><p><strong>${x.count}</strong> new customer${x.count===1?'':'s'}</p></div>`).join('')}</div></section></div>`}

async function appearance(){const d=await api('/api/admin/settings'),s=d.settings;$('#adminContent').innerHTML=`<section class="admin-panel"><div class="admin-panel-head"><div><span class="eyebrow">THEME</span><h2>Appearance</h2></div></div><p class="muted">Choose the default visual system and whether customers can override it.</p><form id="appearanceForm" class="form-grid"><div class="field"><label>Default theme</label><select name="defaultTheme"><option value="midnight" ${s.default_theme==='midnight'?'selected':''}>Midnight</option><option value="pearl" ${s.default_theme==='pearl'?'selected':''}>Pearl</option></select></div><label class="setting-toggle"><div><strong>Allow customer theme choice</strong><span>Customers can choose Midnight or Pearl.</span></div><input class="switch" name="allowUserTheme" type="checkbox" ${s.allow_user_theme!==false?'checked':''}></label><button class="btn btn-primary">Save appearance</button></form></section>`;$('#appearanceForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;try{await api('/api/admin/settings',{method:'PATCH',body:{settings:{default_theme:f.elements.defaultTheme.value,allow_user_theme:f.elements.allowUserTheme.checked}}});toast('Appearance saved.')}catch(err){toast(err.message,'error')}})}

async function settings(){const d=await api('/api/admin/settings'),s=d.settings;$('#adminContent').innerHTML=`<section class="admin-panel"><div class="admin-panel-head"><div><span class="eyebrow">GLOBAL</span><h2>Ecosystem settings</h2></div></div><form id="settingsForm" class="form-grid"><div class="field"><label>Support email</label><input name="supportEmail" type="email" value="${esc(s.support_email||'')}"></div>${toggleRow('dockApps','Tools dock section',s.dock_apps_enabled)}${toggleRow('dockUpdates','Updates dock section',s.dock_updates_enabled)}${toggleRow('dockRequests','Requests dock section',s.dock_requests_enabled)}${toggleRow('dockSettings','Settings dock section',s.dock_settings_enabled)}${toggleRow('requestAttachments','Request attachments',s.request_attachments_enabled)}${toggleRow('floatingPromo','Floating promotions',s.floating_promo_enabled)}<button class="btn btn-primary">Save settings</button></form></section><section class="admin-panel" style="margin-top:14px"><div class="admin-panel-head"><h2>Promotions</h2><button class="btn btn-secondary compact" data-action="promo-new">Add campaign</button></div><p class="muted">Campaign creation is available in V1.0. Rotation and audience expansion can be extended without schema changes.</p><div id="promoList"></div></section>`;$('#settingsForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;try{await api('/api/admin/settings',{method:'PATCH',body:{settings:{support_email:f.elements.supportEmail.value,dock_apps_enabled:f.elements.dockApps.checked,dock_updates_enabled:f.elements.dockUpdates.checked,dock_requests_enabled:f.elements.dockRequests.checked,dock_settings_enabled:f.elements.dockSettings.checked,request_attachments_enabled:f.elements.requestAttachments.checked,floating_promo_enabled:f.elements.floatingPromo.checked}}});toast('Settings saved.')}catch(err){toast(err.message,'error')}});const p=await api('/api/admin/promos');$('#promoList').innerHTML=p.promos.length?p.promos.map(x=>`<div class="timeline-item"><small>${human(x.display_mode)} · ${x.enabled?'Enabled':'Disabled'}</small><p><strong>${esc(x.title)}</strong><br>${esc(x.message)}</p></div>`).join(''):empty('No promotions','Create a campaign when needed.')}
function toggleRow(name,label,checked){return `<label class="setting-toggle"><div><strong>${esc(label)}</strong></div><input class="switch" name="${name}" type="checkbox" ${checked!==false?'checked':''}></label>`}
function promoForm(){return `<h2>New promotion</h2><form id="promoForm" class="form-grid"><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Message</label><textarea name="message" required></textarea></div><div class="field"><label>Destination URL</label><input name="destinationUrl" type="url"></div><div class="admin-form-row"><div class="field"><label>Display</label><select name="displayMode"><option value="card">Card</option><option value="popup">Popup</option><option value="floating">Floating</option></select></div><div class="field"><label>Opening delay (ms)</label><input name="openingDelayMs" type="number" value="2500"></div></div><label class="setting-toggle"><div><strong>Enabled</strong></div><input class="switch" name="enabled" type="checkbox" checked></label><button class="btn btn-primary">Create campaign</button></form>`}
function bindPromoForm(){const f=$('#promoForm');f?.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(f);try{await api('/api/admin/promos',{method:'POST',body:{title:d.get('title'),message:d.get('message'),destinationUrl:d.get('destinationUrl'),displayMode:d.get('displayMode'),openingDelayMs:Number(d.get('openingDelayMs')),enabled:f.elements.enabled.checked}});closeModal();toast('Promotion created.');loadTab('settings')}catch(err){toast(err.message,'error')}})}


async function auditLog(){const d=await api('/api/admin/audit');$('#adminContent').innerHTML=`<section class="admin-panel"><div class="admin-panel-head"><div><span class="eyebrow">ACCOUNTABILITY</span><h2>Administrator audit log</h2></div></div>${d.logs.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Administrator</th><th>Action</th><th>Target</th><th>Time</th></tr></thead><tbody>${d.logs.map(x=>`<tr><td><strong>${esc(x.admin_name||'System')}</strong><br>${esc(x.admin_email||'')}</td><td>${esc(human(x.action))}</td><td>${esc(human(x.target_type||''))} ${esc(x.target_id||'')}</td><td>${fmtDate(x.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No audit entries','Important administrator actions will appear here.')}</section>`}

async function diagnostics(){const d=await api('/api/admin/diagnostics');$('#adminContent').innerHTML=`<div class="diag-grid">${Object.entries(d.checks).map(([k,v])=>`<article class="diag-card"><span class="diag-status ${v?'ok':'bad'}">${v?'READY':'NOT CONFIGURED'}</span><strong>${esc(human(k))}</strong><p class="muted">${v?'Binding or secret detected.':'Configure this production dependency.'}</p></article>`).join('')}</div><section class="admin-panel" style="margin-top:14px"><div class="admin-panel-head"><h2>Runtime</h2></div><p class="muted">ToolCart ${esc(d.version)}. ${esc(d.note)}</p></section>`}

async function handleOpen(type,id){if(type==='customer')return openCustomer(id);if(type==='app'){const a=state.cache.appMeta.apps.find(x=>x.id===Number(id));showModal(appForm(a));return bindAppForm()}if(type==='product'){const p=state.cache.products?.find(x=>x.id===Number(id));showModal(productForm(p));return bindProductForm()}if(type==='plan'){const p=state.cache.plans.find(x=>x.id===Number(id));showModal(planForm(p));return bindPlanForm()}if(type==='request')return openAdminRequest(id);if(type==='update'){const u=state.cache.updates.find(x=>x.id===Number(id));return showModal(`<div class="detail-hero"><span class="eyebrow">${esc(human(u.update_type))}</span><h2>${esc(u.title)}</h2><p>${esc(u.summary)}</p>${badge(u.status)}</div><p style="white-space:pre-wrap;color:var(--muted);line-height:1.6">${esc(u.content)}</p><button class="btn btn-secondary admin-danger" data-action="update-delete" data-id="${u.id}">Delete update</button>`)}}
async function handleAction(el){const a=el.dataset.action,id=el.dataset.id;if(a==='asset-new'){const kind=state.assetView==='products'?'product':'app';showModal(creatorModal(kind));return kind==='product'?bindProductForm():bindAppForm()}if(a==='app-new'){state.assetView='tools';showModal(creatorModal('app'));return bindAppForm()}if(a==='app-delete'){if(!confirm('Delete this tool from ToolCart?'))return;try{await api(`/api/admin/apps/${id}`,{method:'DELETE'});closeModal();toast('Tool deleted.');loadTab('apps')}catch(e){toast(e.message,'error')}return}if(a==='product-new'){state.assetView='products';showModal(creatorModal('product'));return bindProductForm()}if(a==='product-delete'){if(!confirm('Delete this product? Products with purchase history cannot be deleted.'))return;try{await api(`/api/admin/products/${id}`,{method:'DELETE'});closeModal();toast('Product deleted.');state.assetView='products';loadTab('apps')}catch(e){toast(e.message,'error')}return}if(a==='plan-new'){showModal(planForm());return bindPlanForm()}if(a==='update-new'){showModal(updateForm());return bindUpdateForm()}if(a==='update-delete'){if(!confirm('Delete this update?'))return;try{await api(`/api/admin/updates/${id}`,{method:'DELETE'});closeModal();toast('Update deleted.');loadTab('updates')}catch(e){toast(e.message,'error')}return}if(a==='notification-new'){showModal(notificationForm());return bindNotificationForm()}if(a==='promo-new'){showModal(promoForm());return bindPromoForm()}if(a==='customer-disable'){const d=await api(`/api/admin/customers/${id}`);const action=d.user.status==='disabled'?'restore':'disable';if(!confirm(`${human(action)} this account?`))return;await api(`/api/admin/customers/${id}/action`,{method:'POST',body:{action}});closeModal();toast('Customer updated.');loadTab('customers');return}if(a==='customer-delete'){const email=el.dataset.email;const typed=prompt(`Type ${email} to confirm permanent deletion.`);if(typed!==email)return;await api(`/api/admin/customers/${id}/action`,{method:'POST',body:{action:'delete',confirm:typed}});closeModal();toast('Customer deleted.');loadTab('customers');return}if(a==='customer-notify'){showModal(`<h2>Notify customer</h2><form id="customerNotifyForm" class="form-grid"><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Message</label><textarea name="message" required></textarea></div><button class="btn btn-primary">Send</button></form>`);$('#customerNotifyForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api(`/api/admin/customers/${id}/action`,{method:'POST',body:{action:'send_notification',title:f.get('title'),message:f.get('message')}});closeModal();toast('Notification sent.')});return}if(a==='customer-wallet'){const d=await api(`/api/admin/customers/${id}`);showModal(`<h2>Adjust customer balance</h2><p class="modal-sub">Current balance: <strong>${fmtMoney(d.wallet?.balanceMinor||0,d.wallet?.currency||'NGN')}</strong></p><form id="walletAdjustForm" class="form-grid"><div class="field"><label>Amount</label><input name="amount" type="number" step="0.01" required placeholder="5000 or -1000"></div><div class="field"><label>Currency</label><input name="currency" value="${esc(d.wallet?.currency||'NGN')}" maxlength="3"></div><div class="field"><label>Note</label><input name="note" placeholder="Manual funding or correction"></div><button class="btn btn-primary">Apply adjustment</button></form>`);$('#walletAdjustForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const amountMinor=Math.round(Number(f.get('amount')||0)*100);try{await api(`/api/admin/customers/${id}/action`,{method:'POST',body:{action:'wallet_adjust',amountMinor,currency:f.get('currency'),note:f.get('note')}});toast('Balance updated.');return openCustomer(id)}catch(err){toast(err.message,'error')}});return}if(a==='customer-gift'){const p=await api('/api/admin/subscriptions/plans');showModal(`<h2>Gift subscription</h2><form id="giftForm" class="form-grid"><div class="field"><label>Plan</label><select name="planId">${p.plans.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Days</label><input name="days" type="number" min="1" value="30"></div><button class="btn btn-primary">Gift subscription</button></form>`);$('#giftForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api(`/api/admin/customers/${id}/action`,{method:'POST',body:{action:'gift_subscription',planId:Number(f.get('planId')),days:Number(f.get('days'))}});closeModal();toast('Subscription gifted.')});return}}

function showModal(html){$('#adminModalContent').innerHTML=html;$('#modalBackdrop').classList.remove('hidden');$('#adminModal').classList.remove('hidden');document.body.style.overflow='hidden'}
function closeModal(){$('#modalBackdrop').classList.add('hidden');$('#adminModal').classList.add('hidden');document.body.style.overflow=''}
function showMore(){showModal(`<h2>Admin sections</h2><div class="admin-more-sheet">${['subscriptions','payments','updates','notifications','analytics','appearance','settings','audit','diagnostics'].map(x=>`<button data-admin-tab="${x}" data-close-admin-modal>${human(x)}</button>`).join('')}</div>`)}
async function optimizeImage(file,max=512,quality=.86){const bmp=await createImageBitmap(file);const scale=Math.min(1,max/Math.max(bmp.width,bmp.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(bmp.width*scale));c.height=Math.max(1,Math.round(bmp.height*scale));c.getContext('2d',{alpha:false}).drawImage(bmp,0,0,c.width,c.height);bmp.close?.();return new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(new File([b],'icon.webp',{type:'image/webp'})):reject(new Error('Could not optimize image.')),'image/webp',quality))}
boot();
